<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('units.edit');verify_csrf();
$id=(int)($_POST['id']??0);$data=[trim($_POST['unit_code']),trim($_POST['unit_name']),trim($_POST['category']),trim($_POST['brand']),trim($_POST['model']),trim($_POST['serial_number']),trim($_POST['location']),$_POST['meter_type'],(float)$_POST['current_meter'],$_POST['operational_status']];
try{if($id){$old=$pdo->prepare('SELECT operational_status FROM units WHERE id=?');$old->execute([$id]);$oldStatus=$old->fetchColumn();$data[]=$id;$pdo->prepare('UPDATE units SET unit_code=?,unit_name=?,category=?,brand=?,model=?,serial_number=?,location=?,meter_type=?,current_meter=?,operational_status=? WHERE id=?')->execute($data);if($oldStatus!==$_POST['operational_status'])add_history($pdo,'unit',$id,$oldStatus,$_POST['operational_status'],'Perubahan dari form unit');audit($pdo,'UPDATE','unit',$id,'Memperbarui '.trim($_POST['unit_code']));}else{$pdo->prepare('INSERT INTO units(unit_code,unit_name,category,brand,model,serial_number,location,meter_type,current_meter,operational_status,qr_token) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute(array_merge($data,['UNIT-'.bin2hex(random_bytes(12))]));$id=(int)$pdo->lastInsertId();audit($pdo,'CREATE','unit',$id,'Menambah '.trim($_POST['unit_code']));}flash('success','Data unit berhasil disimpan.');}catch(Throwable $e){flash('error','Gagal menyimpan unit: '.$e->getMessage());}redirect('../'.page_url('units'));
